package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

public class JavaScriptDimFilterExploitTest
{
  @Test
  public void testExploit() throws Exception
  {
    ObjectMapper mapper = new ObjectMapper();
    JavaScriptConfig disabledConfig = new JavaScriptConfig(false);
    InjectableValues.Std injectableValues = new InjectableValues.Std();
    injectableValues.addValue(JavaScriptConfig.class, disabledConfig);
    mapper.setInjectableValues(injectableValues);

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"function\": \"function(x){return x}\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    try {
        JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);
        // If we reach here, we need to check if the filter allows execution.
        // The check happens in getPredicateFactory() or similar methods which calls config.isEnabled()
        filter.toFilter();

        // If it didn't throw, it means the config was overridden or ignored in a way that allows execution.
        Assert.fail("Should have thrown IllegalStateException because JavaScript is disabled.");
    } catch (IllegalStateException e) {
        Assert.assertEquals("JavaScript is disabled", e.getMessage());
    }
  }
}

